contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _value) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        uint beforeBalanceC = address(c).balance;
        uint beforeBalanceTest = address(this).balance;

        bool reverted;
        c.withdraw(_value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted || (address(c).balance == beforeBalanceC - _value && address(this).balance == beforeBalanceTest + _value));
    }

    receive() external payable {}
}

